methods.deltint:
def deltint(self):
    old_phase = self.phase
    if old_phase == "PREPARE":
        self.in_flight = True
        self.is_retry_next_send = True
        self._next_out_data = None
        self.hold_in("WAIT_ACK", float(self.timeout))
        return
    if old_phase == "WAIT_ACK":
        if self.session_started and self.in_flight and self.current_seq <= self.total_packets:
            self._next_out_data = {"seq_num": int(self.current_seq), "bit": int(self.current_bit)}
            self.logger.info({"time": float(get_current_time()), "entity": "sender", "event": "delay_start", "payload": {"type": "preparation", "duration": float(self.sender_delay)}}, log_type="PROCESS")
            self.hold_in("PREPARE", float(self.sender_delay))
        else:
            self.hold_in("DONE", float("inf"))

methods.deltext:
def deltext(self, e: float):
    remaining = float(self.ta()) - float(e)
    if remaining < 0.0:
        remaining = 0.0

    for msg in self.input["in_start"].values:
        if isinstance(msg, dict) and "total_packets" in msg:
            self.total_packets = int(msg["total_packets"])
            self.session_started = True
            self.current_seq = 1
            self.current_bit = 0
            self._next_out_data = {"seq_num": int(self.current_seq), "bit": int(self.current_bit)}
            self.logger.info({"time": float(get_current_time()), "entity": "sender", "event": "delay_start", "payload": {"type": "preparation", "duration": float(self.sender_delay)}}, log_type="PROCESS")
            self.hold_in("PREPARE", float(self.sender_delay))
            return

    for ack in self.input["in_ack"].values:
        if not (isinstance(ack, dict) and "ack_bit" in ack):
            continue
        ack_bit = int(ack["ack_bit"])
        is_valid = bool(ack_bit == int(self.current_bit))
        self.logger.info({"time": float(get_current_time()), "entity": "sender", "event": "ack_received", "payload": {"ack_bit": int(ack_bit), "is_valid": bool(is_valid)}}, log_type="PROCESS")

