    snapshot_matched = None
    if self._active_req is not None:
        active_rid = self._active_req.get("request_id", "")
        for snap in self.input["eval_snapshot_resp_in"].values:
            if snap.get("request_id", "") == active_rid:
                snapshot_matched = snap
                break

    if self.phase == self.param["idle_phase"]:
        if self._active_req is None and self._req_queue:
            self._active_req = self._req_queue.pop(0)
            self._prepare_snapshot_request(self._active_req)
            self.hold_in(self.param["send_snapshot_phase"], 0.0)
            return
        self.hold_in(self.param["idle_phase"], float("inf"))
        return

    if self.phase == self.param["wait_snapshot_phase"] and snapshot_matched is not None and self._active_req is not None:
        self._pending_eval_resp_payload = self._evaluate_from_snapshot(self._active_req, snapshot_matched)
        self.hold_in(self.param["send_eval_phase"], 0.0)

