methods.deltext:
def deltext(self, e: float):
    for req in self.input["obs_req_in"].values:
        if isinstance(req, dict):
            self._req_queue.append(self._normalize_req(req))

    for snap in self.input["obs_snapshot_resp_in"].values:
        if not isinstance(snap, dict):
            continue
        if self._pending_req is None:
            continue
        pending_id = self._pending_req.get("request_id", "")
        snap_id = snap.get("request_id", "")
        if isinstance(snap_id, str) and snap_id == pending_id and self.phase == self.param["phases"]["WAIT_SNAPSHOT"]:
            self._prepared_obs_resp = self._build_obs_resp(self._pending_req, snap)
            self._prepared_snapshot_req = None
            self.hold_in(self.param["phases"]["SEND_OBS_RESP"], 0.0)
            return

    if self.phase == self.param["phases"]["READY"] and self._pending_req is None:
        self._prepare_next_snapshot_request_if_idle()
        return

